-- GENERATED by backend/scripts/gen_exercise_seed.py from shared/exercise-library.json — do not edit by hand.
-- Seeds the 20-exercise library (F11). Upserts on slug, so it is safe to re-run.

insert into public.exercises (slug, name, body_area, description, instructions, positioning_tip, sensor_mode, diagram, default_sets, default_reps, target_angle_deg, return_angle_deg, target_rotation_deg, est_minutes, difficulty, equipment, tags, accent_color) values
  ('shoulder-flexion', 'Shoulder Flexion', 'Shoulder', 'Raise your straight arm forward and up to shoulder height, then lower it with control.', '["Stand or sit tall with your arm relaxed at your side.", "Keep still for a moment so the app can find your starting position.", "Slowly raise your straight arm forward and up toward shoulder height.", "Pause, then lower your arm back down to your side with control."]'::jsonb, 'Hold the phone in your exercising hand, screen facing your body. No mount or strap needed.', 'tilt', 'raise-front', 3, 10, 70, 20, null, 5, 'easy', 'none', array['range of motion', 'post-op', 'rotator cuff']::text[], '#2C5F8A'),
  ('shoulder-abduction', 'Shoulder Abduction', 'Shoulder', 'Lift your straight arm out to the side to shoulder height, then lower it.', '["Stand or sit tall with your arm relaxed at your side, palm facing in.", "Keep still for a moment so the app can find your starting position.", "Slowly lift your straight arm out to the side, up toward shoulder height.", "Pause, then lower your arm back down to your side with control."]'::jsonb, 'Hold the phone in your exercising hand, screen facing your leg.', 'tilt', 'raise-side', 3, 10, 70, 20, null, 5, 'easy', 'none', array['range of motion', 'rotator cuff']::text[], '#6B4FA0'),
  ('shoulder-circles', 'Shoulder Circles', 'Shoulder', 'Make big, slow circles with your whole straight arm.', '["Stand with your arm relaxed at your side.", "Keep still for a moment so the app is ready.", "Slowly swing your straight arm in one big, smooth circle.", "Keep a slow, steady pace until the app tells you the circle is complete."]'::jsonb, 'Hold the phone loosely in your exercising hand.', 'rotation', 'circle-shoulder', 2, 6, null, null, 360, 4, 'easy', 'none', array['warm-up', 'mobility']::text[], '#B7791F'),
  ('pendulum', 'Pendulum Circles', 'Shoulder', 'Lean forward on a table and let your arm hang, drawing small gentle circles.', '["Lean forward and rest your free hand on a sturdy table or counter.", "Let your exercising arm hang straight down and relax your shoulder.", "Keep still for a moment so the app is ready.", "Gently sway your body so your hanging arm draws small circles. Let gravity do the work."]'::jsonb, 'Hold the phone loosely in the hanging hand. Use a light grip so you don''t tense your shoulder.', 'rotation', 'circle-shoulder', 2, 8, null, null, 300, 4, 'easy', 'table or counter', array['post-op', 'gentle', 'mobility']::text[], '#8A5A2C'),
  ('shoulder-external-rotation', 'Shoulder External Rotation', 'Shoulder', 'With your elbow tucked at your side, swing your forearm outward and back.', '["Stand tall. Bend your elbow to 90 degrees and tuck it against your side.", "Keep still for a moment so the app is ready.", "Keeping your elbow against your side, slowly rotate your forearm outward.", "Return your hand to the front of your belly. Out and back counts as one rep."]'::jsonb, 'Hold the phone flat in your palm, screen up, like carrying a tray.', 'rotation', 'dial', 3, 10, null, null, 100, 5, 'moderate', 'optional towel roll under the elbow', array['rotator cuff', 'strength']::text[], '#2C7A8A'),
  ('elbow-flexion', 'Elbow Bend (Bicep Curl)', 'Elbow & Wrist', 'Bend your elbow to bring your hand toward your shoulder, then straighten it.', '["Sit or stand with your arm straight down at your side, palm facing forward.", "Keep still for a moment so the app can find your starting position.", "Keeping your upper arm still, bend your elbow and bring your hand up toward your shoulder.", "Slowly straighten your arm back down."]'::jsonb, 'Hold the phone in your exercising hand like a light weight, screen facing forward.', 'tilt', 'dial', 3, 12, 90, 25, null, 5, 'easy', 'none', array['strength', 'range of motion']::text[], '#9C4221'),
  ('wrist-flexion-extension', 'Wrist Up and Down', 'Elbow & Wrist', 'With your forearm resting on a table, tip your hand up, then back down.', '["Rest your forearm on a table with your hand hanging over the edge, palm down.", "Keep still for a moment so the app can find your starting position.", "Slowly bend your wrist to lift the back of your hand up toward the ceiling.", "Lower your hand back to the start. Keep your forearm on the table."]'::jsonb, 'Hold the phone flat in your palm. Your forearm stays on the table the whole time.', 'tilt', 'dial', 2, 12, 35, 10, null, 4, 'easy', 'table', array['range of motion', 'fracture recovery']::text[], '#227A3D'),
  ('forearm-rotation', 'Forearm Turns', 'Elbow & Wrist', 'With your elbow bent, turn your palm to face down, then back to the start.', '["Sit with your elbow bent at 90 degrees and tucked at your side, thumb pointing up.", "Keep still for a moment so the app can find your starting position.", "Slowly turn your forearm so your palm faces the floor.", "Turn back until your thumb points up again."]'::jsonb, 'Hold the phone upright in your hand, like holding a glass of water.', 'tilt', 'dial', 2, 10, 70, 20, null, 4, 'easy', 'none', array['range of motion', 'fracture recovery']::text[], '#3D6B22'),
  ('wrist-circles', 'Wrist Circles', 'Elbow & Wrist', 'Rotate just your wrist in a slow, gentle circle.', '["Rest your elbow on a table or the arm of a chair.", "Keep still for a moment so the app is ready.", "Slowly rotate your wrist in a smooth circle.", "Keep a slow, steady pace until the app tells you the circle is complete."]'::jsonb, 'Hold the phone loosely in your hand.', 'rotation', 'circle-wrist', 2, 8, null, null, 360, 3, 'easy', 'table or armchair', array['warm-up', 'mobility', 'arthritis']::text[], '#1F7A6B'),
  ('seated-marching', 'Seated Marching', 'Hip', 'Sitting tall, lift one knee up a few inches, then set your foot back down.', '["Sit near the front of a sturdy chair with both feet flat on the floor.", "Keep still for a moment so the app can find your starting position.", "Lift one knee up a few inches, like marching in place.", "Lower your foot back to the floor with control."]'::jsonb, 'Rest the phone flat on top of your thigh, just above the knee, and hold it there with your hand.', 'tilt', 'dial', 2, 10, 20, 6, null, 4, 'easy', 'sturdy chair', array['strength', 'balance', 'fall prevention']::text[], '#6B4FA0'),
  ('standing-hip-abduction', 'Standing Side Leg Lift', 'Hip', 'Holding a counter for balance, lift your straight leg out to the side.', '["Stand behind a sturdy counter or chair and hold on with both hands.", "Keep still for a moment so the app can find your starting position.", "Keeping your toes pointing forward, slowly lift one straight leg out to the side.", "Lower it back down. Keep your body upright, don''t lean."]'::jsonb, 'Slip the phone into a snug front pocket on the leg you''re lifting, or tuck it into the waistband of snug leggings on that side.', 'tilt', 'dial', 2, 10, 18, 6, null, 4, 'moderate', 'counter or sturdy chair', array['strength', 'balance', 'hip replacement']::text[], '#5A4F8A'),
  ('glute-bridge', 'Bridge', 'Hip', 'Lying on your back with knees bent, lift your hips up off the bed, then lower.', '["Lie on your back on a bed or mat with your knees bent and feet flat.", "Keep still for a moment so the app can find your starting position.", "Squeeze your buttocks and slowly lift your hips up off the bed.", "Hold for a moment, then lower your hips back down."]'::jsonb, 'Rest the phone flat on top of one thigh, near the knee, and hold it in place with your hand.', 'tilt', 'dial', 2, 10, 22, 8, null, 5, 'moderate', 'bed or mat', array['strength', 'lower back']::text[], '#8A2C5F'),
  ('seated-knee-extension', 'Seated Knee Straightening', 'Knee', 'Sitting in a chair, straighten your knee to lift your foot, then lower it.', '["Sit tall in a sturdy chair with both feet flat on the floor.", "Keep still for a moment so the app can find your starting position.", "Slowly straighten one knee until your leg is out in front of you.", "Hold for a moment, then slowly bend your knee to lower your foot."]'::jsonb, 'Tuck the phone into a snug sock or ankle band on the front of your shin, screen facing out.', 'tilt', 'dial', 3, 10, 55, 15, null, 5, 'easy', 'sturdy chair', array['strength', 'knee replacement']::text[], '#2C5F8A'),
  ('heel-slides', 'Heel Slides', 'Knee', 'Lying on your back, slide your heel toward your buttocks to bend your knee, then slide it back.', '["Lie on your back on a bed with both legs straight.", "Keep still for a moment so the app can find your starting position.", "Slowly slide one heel toward your buttocks, bending your knee as far as is comfortable.", "Slide your heel back down until your leg is straight."]'::jsonb, 'Tuck the phone into a snug sock or ankle band on the front of your shin.', 'tilt', 'dial', 2, 10, 35, 10, null, 4, 'easy', 'bed or mat', array['range of motion', 'knee replacement', 'post-op']::text[], '#1F6B7A'),
  ('straight-leg-raise', 'Straight Leg Raise', 'Knee', 'Lying on your back, lift one straight leg up to the height of your other knee.', '["Lie on your back. Bend one knee with that foot flat; keep the other leg straight.", "Keep still for a moment so the app can find your starting position.", "Tighten the thigh of your straight leg and lift it up to the height of your bent knee.", "Slowly lower it back down."]'::jsonb, 'Rest the phone flat on the thigh of the straight leg and hold it there with your hand.', 'tilt', 'dial', 3, 10, 30, 8, null, 5, 'moderate', 'bed or mat', array['strength', 'knee replacement']::text[], '#7A5A1F'),
  ('sit-to-stand', 'Sit to Stand', 'Knee', 'Stand up from a chair without using your hands if you can, then sit back down slowly.', '["Sit near the front of a sturdy chair with your feet flat and hip-width apart.", "Keep still for a moment so the app can find your starting position.", "Lean forward slightly and stand all the way up. Use the armrests if you need to.", "Slowly sit back down with control. Don''t drop into the chair."]'::jsonb, 'Hold the phone flat against the top of your thigh with one hand.', 'tilt', 'dial', 2, 8, 60, 15, null, 5, 'moderate', 'sturdy chair with armrests', array['strength', 'fall prevention', 'daily function']::text[], '#0E6E66'),
  ('mini-squat', 'Mini Squat', 'Knee', 'Holding a counter, bend your knees a little as if starting to sit, then stand back up.', '["Stand facing a sturdy counter and hold on with both hands, feet hip-width apart.", "Keep still for a moment so the app can find your starting position.", "Slowly bend your knees a small amount, keeping your heels on the floor.", "Straighten back up to standing."]'::jsonb, 'Slip the phone into a snug front pants pocket, or tuck it into the waistband of snug leggings over one thigh.', 'tilt', 'dial', 2, 10, 25, 8, null, 4, 'moderate', 'counter', array['strength', 'balance']::text[], '#5F2C8A'),
  ('ankle-pumps', 'Ankle Pumps', 'Ankle & Foot', 'Point your toes up toward you, then down away from you, like pressing a gas pedal.', '["Sit or lie with your leg straight out in front of you and your heel resting down.", "Keep still for a moment so the app can find your starting position.", "Pull your toes up toward your nose as far as is comfortable.", "Point your toes back down. Up and back counts as one rep."]'::jsonb, 'Tuck the phone into a snug sock on the top of your foot.', 'tilt', 'dial', 2, 15, 20, 6, null, 3, 'easy', 'none', array['circulation', 'post-op', 'range of motion']::text[], '#227A3D'),
  ('seated-trunk-rotation', 'Seated Trunk Twist', 'Back & Core', 'Sitting tall with arms crossed, turn your upper body gently to one side and back.', '["Sit tall in a chair with feet flat and arms crossed over your chest.", "Keep still for a moment so the app is ready.", "Slowly turn your shoulders and head to one side, as far as is comfortable.", "Turn back to the middle. Out and back counts as one rep; alternate sides."]'::jsonb, 'Hold the phone flat against your chest under your crossed arms.', 'rotation', 'dial', 2, 10, null, null, 70, 4, 'easy', 'chair', array['mobility', 'lower back']::text[], '#9C4221'),
  ('standing-side-bend', 'Standing Side Bend', 'Back & Core', 'Standing tall, slide one hand down the side of your leg to bend sideways, then straighten.', '["Stand tall with feet hip-width apart, near a counter in case you need support.", "Keep still for a moment so the app can find your starting position.", "Slowly lean to one side, sliding your hand down the outside of your leg.", "Return to standing tall. Alternate sides."]'::jsonb, 'Hold the phone flat against the middle of your chest with your other hand.', 'tilt', 'dial', 2, 8, 18, 5, null, 3, 'easy', 'none', array['mobility', 'lower back']::text[], '#2C5F8A')
